import { ParameterSpecRecord } from "#base/scripts/voronoi-types.js";

import { RegionCell, VoronoiUtils } from "../voronoi-utils.js";
import { Rule, ScoringContext } from "../voronoi_rules/rules-base.js";

const ruleSchema = {
	scaleFactor: {
		label: "Scale Factor %",
		description:
			"The distance from the region seed as a percentage of map width that represents a score of 0.5. Any cell nearer to the region seed will score between 0.5 and 1.0, and any cell farther away will score between 0.0 and 0.5",
		default: 20,
		min: 0,
		max: 100,
		step: 0.1,
	},
	invert: {
		label: "Invert",
		description: "Invert the calculation to prefer tile further away from the region seed.",
		default: 0,
		min: 0,
		max: 1,
		step: 1,
	},
} as const satisfies ParameterSpecRecord;

export class RuleNearRegionSeed extends Rule {
	override parameterSpecs = ruleSchema;
	override configValues = Rule.createDefaultsFromSpecs(ruleSchema);
	override name = RuleNearRegionSeed.getName();
	override description = "This rule scores cells nearer to the region seed higher than cells farther away.";

	static getName(): string {
		return "Near Region Seed";
	}

	static getSchema() {
		return ruleSchema;
	}

	score(regionCell: RegionCell, ctx: ScoringContext): number {
		let distanceToSeed: number = VoronoiUtils.sqDistance(
			{ x: ctx.region.seedLocation.x, y: ctx.region.seedLocation.y },
			{ x: regionCell.cell.site.x, y: regionCell.cell.site.y },
			ctx.wrap,
		);
		distanceToSeed = Math.sqrt(distanceToSeed);
		let scaleFactor = this.configValues.scaleFactor * 0.01 * ctx.m_worldDims.x;
		scaleFactor *= 0.5; // Treat like radius instead of diameter so 100% means from the center to the edge.
		let score = distanceToSeed / (distanceToSeed + scaleFactor);
		if (!this.configValues.invert) {
			score = 1 - score;
		}
		return score;
	}
}
